        /// <summary>The sides of a block that are full, a mask of North, South, West
        /// and East: what a state leaves unsaid is its default, and a name the game
        /// does not have has none.</summary>
        public static int FullSides(BlockState state)
        {
            if (!ByState.TryGetValue(state.Name, out var read))
                return Whole.Contains(state.Name) ? 15 : Sides.TryGetValue(state.Name, out int mask) ? mask : 0;
            var values = new string[read.Keys.Length];
            for (int i = 0; i < values.Length; i++)
                values[i] = state.GetProperty(read.Keys[i]) ?? DefaultOf(state.Name, read.Keys[i]);
            return read.Masks.TryGetValue(string.Join(",", values), out int sides) ? sides : 0;
        }

        private static string DefaultOf(string name, string key)
        {
            foreach (var pair in BlockDefaults.DefaultProperties(name))
                if (pair.Key == key)
                    return pair.Value;
            return "";
        }
    }
}
